//! One scanner iteration inspects at most a byte and one byte of lookahead.
//! Escape and comment delimiters consume two bytes without unbounded searches.
use crate::is_space;

pub(crate) struct Scan {
    pub cursor: usize,
    pub end: usize,
    pub quote: u8,
    comment: bool,
}
impl Scan {
    pub fn new(start: usize, end: usize) -> Self {
        Self {
            cursor: start,
            end,
            quote: 0,
            comment: false,
        }
    }
    pub fn done(&self) -> bool {
        self.cursor >= self.end
    }
    /// Returns only unquoted, uncommented byte events, just like the baseline scanners.
    pub fn tick(&mut self, source: &[u8]) -> Option<(usize, u8)> {
        if self.done() {
            return None;
        }
        let i = self.cursor;
        let c = source[i];
        if self.comment {
            if i + 1 >= self.end {
                self.cursor = self.end;
            } else if c == b'*' && source[i + 1] == b'/' {
                self.cursor += 2;
                self.comment = false;
            } else {
                self.cursor += 1;
            }
        } else if self.quote != 0 {
            if c == b'\\' {
                self.cursor += (self.end - i).min(2);
            } else {
                if c == self.quote {
                    self.quote = 0;
                }
                self.cursor += 1;
            }
        } else if matches!(c, b'\'' | b'"') {
            self.quote = c;
            self.cursor += 1;
        } else if c == b'/' && i + 1 < self.end && source[i + 1] == b'*' {
            self.comment = true;
            self.cursor += 2;
        } else {
            self.cursor += 1;
            return Some((i, c));
        }
        None
    }
}

pub(crate) struct Space {
    pub cursor: usize,
    end: usize,
    comment: bool,
}
impl Space {
    pub fn new(start: usize, end: usize) -> Self {
        Self {
            cursor: start,
            end,
            comment: false,
        }
    }
    /// True means the whitespace/comment run is complete. Each call advances at most two bytes.
    pub fn tick(&mut self, source: &[u8]) -> bool {
        let i = self.cursor;
        if i >= self.end {
            return true;
        }
        if self.comment {
            if i + 1 >= self.end {
                self.cursor = self.end;
                self.comment = false;
            } else if source[i] == b'*' && source[i + 1] == b'/' {
                self.cursor += 2;
                self.comment = false;
            } else {
                self.cursor += 1;
            }
        } else if is_space(source[i]) {
            self.cursor += 1;
        } else if source[i] == b'/' && i + 1 < self.end && source[i + 1] == b'*' {
            self.cursor += 2;
            self.comment = true;
        } else {
            return true;
        }
        false
    }
}

use crate::declarations::Declarations;
use crate::matching::{Attribute, SelectorMatcher};
use crate::{
    CssError, CssPaint, CssSheet, CssValue, Declaration, MAX_BYTES, MAX_DECLARATIONS,
    MAX_RULE_MATCHES, PROPERTY_COUNT, Property, Winner, checked_slice, control, inherited,
    is_element, offer, span_eq,
};
use vexel_base::{ControlledError, ControlledStep, WorkControl, WorkKind};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Phase {
    Initialize,
    Reset,
    Rule,
    Match,
    Offer,
    Presentation,
    InlineAttribute,
    InlineParse,
    InlineOffer,
    Winner,
    Done,
}

/// An exclusive temporary sheet borrow with independent source and paint lifetime.
/// The parent is copied on entry; the only public paint result is produced by successful finish.
/// Units count token visits, byte comparisons, parser operations, rule tests and cascade entries.
pub struct CssComputeSession<'ctx, 'src> {
    sheet: &'ctx mut CssSheet<'src>,
    element: usize,
    parent: Option<CssPaint<'src>>,
    paint: CssPaint<'src>,
    winners: [Option<Winner>; PROPERTY_COUNT],
    terminal: Option<Result<(), ControlledError<CssError>>>,
    phase: Phase,
    property: usize,
    rule: usize,
    declaration: usize,
    matcher: Option<SelectorMatcher<'src>>,
    attribute: Option<Attribute>,
    inline: Option<Declarations>,
}

