#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CssError {
    Limit,
    OutOfMemory,
    Unsupported,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CssValue<'a> {
    pub span: XmlSpan,
    pub bytes: &'a [u8],
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CssPaint<'a> {
    values: [Option<CssValue<'a>>; PROPERTY_COUNT],
    source: Option<&'a [u8]>,
}

impl<'a> CssPaint<'a> {
    pub const fn initial() -> Self {
        Self {
            values: [None; PROPERTY_COUNT],
            source: None,
        }
    }
    pub fn value(&self, property: Property) -> Option<CssValue<'a>> {
        self.values[property as usize]
    }
    pub fn keyword_equals(&self, property: Property, keyword: &[u8]) -> bool {
        self.value(property)
            .is_some_and(|value| value.bytes.eq_ignore_ascii_case(keyword))
    }
}

#[derive(Debug, Clone, Copy)]
struct Term {
    element: Option<XmlSpan>,
    id: Option<XmlSpan>,
    classes: [XmlSpan; MAX_CLASSES],
    class_count: usize,
    specificity: u32,
}
impl Term {
    const EMPTY: Self = Self {
        element: None,
        id: None,
        classes: [XmlSpan {
            offset: 0,
            length: 0,
        }; MAX_CLASSES],
        class_count: 0,
        specificity: 0,
    };
}

#[derive(Debug, Clone, Copy)]
struct Selector {
    terms: [Term; MAX_SELECTOR_TERMS],
    count: usize,
    specificity: u32,
}
impl Selector {
    const EMPTY: Self = Self {
        terms: [Term::EMPTY; MAX_SELECTOR_TERMS],
        count: 0,
        specificity: 0,
    };
}

#[derive(Debug, Clone, Copy)]
struct Declaration {
    property: Property,
    value: XmlSpan,
    important: bool,
}

struct Rule {
    selector: Selector,
    declarations: Vec<Declaration>,
    order: usize,
    unsupported: bool,
}

/// A stylesheet borrows its immutable XML source. Rule values and selectors retain source spans.
pub struct CssSheet<'a> {
    source: &'a [u8],
    tokens: &'a [XmlToken],
    rules: Vec<Rule>,
    declaration_count: usize,
    css_bytes: usize,
    match_tests: usize,
    selector_visits: usize,
    hit_limit: bool,
    allocated_bytes: usize,
}

impl<'src> CssSheet<'src> {
    pub fn create(source: &'src [u8], tokens: &'src [XmlToken]) -> Result<Self, CssError> {
        Self::create_controlled(source, tokens, &mut control::NoStop).map_err(control::legacy_error)
    }

    pub fn create_controlled(
        source: &'src [u8],
        tokens: &'src [XmlToken],
        control: &mut dyn WorkControl,
    ) -> Result<Self, ControlledError<CssError>> {
        let mut session = CssBuildSession::new(source, tokens);
        loop {
            match session.step(256, control) {
                ControlledStep::Pending { .. } => {}
                _ => return session.finish(),
            }
        }
    }

    pub fn rule_count(&self) -> usize {
        self.rules.len()
    }
    pub fn css_bytes(&self) -> usize {
        self.css_bytes
    }

    /// Actual retained rule and nested declaration Vec capacities; borrowed XML is excluded.
    pub fn allocated_bytes(&self) -> usize {
        self.allocated_bytes
    }

    /// The session copies the parent paint. Its temporary borrow cannot shorten source spans.
    pub fn begin_compute<'ctx>(
        &'ctx mut self,
        element: usize,
        parent: Option<&CssPaint<'src>>,
    ) -> CssComputeSession<'ctx, 'src> {
        CssComputeSession::new(self, element, parent.copied())
    }

    pub fn compute(
        &mut self,
        element: usize,
        parent: Option<&CssPaint<'src>>,
    ) -> Result<CssPaint<'src>, CssError> {
        self.compute_controlled(element, parent, &mut control::NoStop)
            .map_err(control::legacy_error)
    }

    pub fn compute_controlled(
        &mut self,
        element: usize,
        parent: Option<&CssPaint<'src>>,
        control: &mut dyn WorkControl,
    ) -> Result<CssPaint<'src>, ControlledError<CssError>> {
        let mut session = self.begin_compute(element, parent);
        loop {
            match session.step(256, control) {
                ControlledStep::Pending { .. } => {}
                _ => return session.finish(),
            }
        }
    }
}

#[derive(Clone, Copy)]
struct Winner {
    value: XmlSpan,
    important: bool,
    specificity: u32,
    order: usize,
}
fn offer(
    winners: &mut [Option<Winner>; PROPERTY_COUNT],
    declaration: Declaration,
    specificity: u32,
    order: usize,
) {
    let slot = &mut winners[declaration.property as usize];
    let wins = slot.is_none_or(|old| {
        declaration.important > old.important
            || (declaration.important == old.important
                && (specificity > old.specificity
                    || (specificity == old.specificity && order >= old.order)))
    });
    if wins {
        *slot = Some(Winner {
            value: declaration.value,
            important: declaration.important,
            specificity,
            order,
        });
    }
}

pub fn is_style_element(source: &[u8], token: &XmlToken) -> bool {
    matches!(
        token.kind,
        TokenKind::StartElement | TokenKind::EmptyElement
    ) && token.prefix.length == 0
        && span_eq(source, token.local_name, b"style")
}

pub fn keyword_equals(source: &[u8], span: XmlSpan, literal: &[u8]) -> bool {
    checked_slice(source, span).is_ok_and(|value| value.eq_ignore_ascii_case(literal))
}
fn is_element(token: &XmlToken) -> bool {
    matches!(
        token.kind,
        TokenKind::StartElement | TokenKind::EmptyElement
    )
}
fn checked_slice(source: &[u8], span: XmlSpan) -> Result<&[u8], CssError> {
    span.slice(source).ok_or(CssError::Limit)
}
fn span_eq(source: &[u8], span: XmlSpan, bytes: &[u8]) -> bool {
    checked_slice(source, span).is_ok_and(|v| v == bytes)
}
fn inherited(property: Property) -> bool {
    !matches!(
        property,
        Property::ClipPath
            | Property::Opacity
            | Property::Display
            | Property::Filter
            | Property::Mask
            | Property::MixBlendMode
            | Property::Isolation
            | Property::VectorEffect
    )
}
fn is_space(c: u8) -> bool {
    matches!(c, b' ' | b'\t' | b'\r' | b'\n' | 0x0c)
}
fn ident(c: u8) -> bool {
    c.is_ascii_alphanumeric() || matches!(c, b'_' | b'-') || c >= 0x80
}

fn reserve<T>(buffer: &mut Vec<T>, additional: usize, exact: bool) -> Result<(), CssError> {
    if exact {
        buffer.try_reserve_exact(additional)
    } else {
        buffer.try_reserve(additional)
    }
    .map_err(|_| CssError::OutOfMemory)
}

//! The stylesheet and inline declaration parser share these real cursors.
use crate::scan::{Scan, Space};
use crate::{
    CssError, Declaration, MAX_DECLARATIONS, PROPERTY_COUNT, Property, XmlSpan, checked_slice,
    ident, is_space,
};

#[derive(Clone, Copy)]
enum Phase {
    Skip,
    Segment,
    NameLeft,
    NameRight,
    ValueLeft,
    ValueRight,
    BackComment,
    Property,
    Mark,
    Word,
    Bang,
    Inside,
    ImportantTrim,
    Push,
    Done,
}

pub(crate) struct Declarations {
    phase: Phase,
    end: usize,
    next: usize,
    scan: Scan,
    space: Space,
    start: usize,
    colon: Option<usize>,
    parens: usize,
    ns: usize,
    ne: usize,
    vs: usize,
    ve: usize,
    back: usize,
    property_index: usize,
    property: Property,
    mark: usize,
    word: usize,
    bang: usize,
    important: bool,
    pub output: Vec<Declaration>,
    pub unsupported: bool,
    pub hit_limit: bool,
}

impl Declarations {
    pub fn new(source: &[u8], span: XmlSpan) -> Result<Self, CssError> {
        let end = span.end().ok_or(CssError::Limit)?;
        checked_slice(source, span)?;
        Ok(Self {
            phase: Phase::Skip,
            end,
            next: span.offset,
            scan: Scan::new(span.offset, end),
            space: Space::new(span.offset, end),
            start: 0,
            colon: None,
            parens: 0,
            ns: 0,
            ne: 0,
            vs: 0,
            ve: 0,
            back: 0,
            property_index: 0,
            property: Property::Fill,
            mark: 0,
            word: 0,
            bang: 0,
            important: false,
            output: Vec::new(),
            unsupported: false,
            hit_limit: false,
        })
    }
    fn next_segment(&mut self) {
        self.space = Space::new(self.next, self.end);
        self.phase = Phase::Skip;
    }
    fn segment(&mut self, end: usize) {
        self.next = self.scan.cursor;
        if let Some(colon) = self.colon.filter(|&c| c < end) {
            self.ns = self.start;
            self.ne = colon;
            self.vs = colon + 1;
            self.ve = end;
            self.phase = Phase::NameLeft;
        } else {
            self.next_segment();
        }
    }
    fn after_value(&mut self) {
        if self.ns == self.ne || self.vs == self.ve {
            self.next_segment();
        } else {
            self.property_index = 0;
            self.phase = Phase::Property;
        }
    }
    /// One bounded scanner, trim, name lookup, or retained declaration append operation.
    pub fn tick(&mut self, source: &[u8]) -> Result<bool, CssError> {
        match self.phase {
            Phase::Skip => {
                if self.space.tick(source) {
                    if self.space.cursor >= self.end {
                        self.phase = Phase::Done;
                    } else {
                        self.start = self.space.cursor;
                        self.colon = None;
                        self.parens = 0;
                        self.scan = Scan::new(self.start, self.end);
                        self.phase = Phase::Segment;
                    }
                }
            }
            Phase::Segment => {
                if self.scan.done() {
                    self.segment(self.end);
                } else if let Some((i, c)) = self.scan.tick(source) {
                    match c {
                        b'(' => self.parens = self.parens.saturating_add(1),
                        b')' => self.parens = self.parens.saturating_sub(1),
                        b':' if self.colon.is_none() => self.colon = Some(i),
                        b';' if self.parens == 0 => self.segment(i),
                        _ => {}
                    }
                }
            }
            Phase::NameLeft => {
                if self.ns < self.ne && is_space(source[self.ns]) {
                    self.ns += 1;
                } else {
                    self.phase = Phase::NameRight;
                }
            }
            Phase::NameRight => {
                if self.ne > self.ns && is_space(source[self.ne - 1]) {
                    self.ne -= 1;
                } else {
                    self.space = Space::new(self.vs, self.ve);
                    self.phase = Phase::ValueLeft;
                }
            }
            Phase::ValueLeft => {
                if self.space.tick(source) {
                    self.vs = self.space.cursor;
                    self.phase = Phase::ValueRight;
                }
            }
            Phase::ValueRight => {
                if self.ve > self.vs && is_space(source[self.ve - 1]) {
                    self.ve -= 1;
                } else if self.ve - self.vs >= 2 && &source[self.ve - 2..self.ve] == b"*/" {
                    self.back = self.ve - 2;
                    self.phase = Phase::BackComment;
                } else {
                    self.after_value();
                }
            }
            Phase::BackComment => {
                // Preserve the baseline reverse search, including its unmatched-comment behavior.
                if self.back > self.vs {
                    if &source[self.back - 1..self.back + 1] == b"/*" {
                        self.ve = self.back - 1;
                        self.phase = Phase::ValueRight;
                    } else {
                        self.back -= 1;
                    }
                } else {
                    self.after_value();
                }
            }
            Phase::Property => {
                if self.property_index == PROPERTY_COUNT {
                    self.unsupported = true;
                    self.next_segment();
                } else {
                    let p = Property::ALL[self.property_index];
                    // A property name is at most 26 bytes; unequal lengths require no byte walk.
                    let name = &source[self.ns..self.ne];
                    if name.eq_ignore_ascii_case(p.name()) {
                        self.property = p;
                        self.mark = self.ve;
                        self.important = false;
                        self.phase = Phase::Mark;
                    } else {
                        self.property_index += 1;
                    }
                }
            }
            Phase::Mark => {
                if self.mark > self.vs && is_space(source[self.mark - 1]) {
                    self.mark -= 1;
                } else {
                    self.word = self.mark;
                    self.phase = Phase::Word;
                }
            }
            Phase::Word => {
                if self.word > self.vs && ident(source[self.word - 1]) {
                    self.word -= 1;
                } else {
                    self.bang = self.word;
                    self.phase = Phase::Bang;
                }
            }
            Phase::Bang => {
                if self.bang > self.vs && is_space(source[self.bang - 1]) {
                    self.bang -= 1;
                } else if self.bang > self.vs
                    && source[self.bang - 1] == b'!'
                    && source[self.word..self.mark].eq_ignore_ascii_case(b"important")
                {
                    self.scan = Scan::new(self.vs, self.bang - 1);
                    self.phase = Phase::Inside;
                } else {
                    self.phase = Phase::Push;
                }
            }
            Phase::Inside => {
                if self.scan.done() {
                    if self.scan.quote == 0 {
                        self.ve = self.bang - 1;
                        self.important = true;
                        self.phase = Phase::ImportantTrim;
                    } else {
                        self.phase = Phase::Push;
                    }
                } else {
                    self.scan.tick(source);
                }
            }
            Phase::ImportantTrim => {
                if self.ve > self.vs && is_space(source[self.ve - 1]) {
                    self.ve -= 1;
                } else {
                    self.phase = Phase::Push;
                }
            }
            Phase::Push => {
                if self.ve > self.vs {
                    if self.output.len() >= MAX_DECLARATIONS {
                        self.hit_limit = true;
                        return Err(CssError::Limit);
                    }
                    crate::reserve(&mut self.output, 1, false)?;
                    self.output.push(Declaration {
                        property: self.property,
                        value: XmlSpan {
                            offset: self.vs,
                            length: self.ve - self.vs,
                        },
                        important: self.important,
                    });
                }
                self.next_segment();
            }
            Phase::Done => return Ok(true),
        }
        Ok(matches!(self.phase, Phase::Done))
    }
}

use crate::declarations::Declarations;
use crate::matching::{Attribute, SelectorMatcher};
use crate::{
    CssError, CssPaint, CssSheet, CssValue, Declaration, MAX_BYTES, MAX_DECLARATIONS,
    MAX_RULE_MATCHES, PROPERTY_COUNT, Property, Winner, checked_slice, control, inherited,
    is_element, offer, span_eq,
};
use vexel_base::{ControlledError, ControlledStep, WorkControl, WorkKind};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Phase {
    Initialize,
    Reset,
    Rule,
    Match,
    Offer,
    Presentation,
    InlineAttribute,
    InlineParse,
    InlineOffer,
    Winner,
    Done,
}

/// An exclusive temporary sheet borrow with independent source and paint lifetime.
/// The parent is copied on entry; the only public paint result is produced by successful finish.
/// Units count token visits, byte comparisons, parser operations, rule tests and cascade entries.
pub struct CssComputeSession<'ctx, 'src> {
    sheet: &'ctx mut CssSheet<'src>,
    element: usize,
    parent: Option<CssPaint<'src>>,
    paint: CssPaint<'src>,
    winners: [Option<Winner>; PROPERTY_COUNT],
    terminal: Option<Result<(), ControlledError<CssError>>>,
    phase: Phase,
    property: usize,
    rule: usize,
    declaration: usize,
    matcher: Option<SelectorMatcher<'src>>,
    attribute: Option<Attribute>,
    inline: Option<Declarations>,
}

#[cfg(test)]
#[path = "compute_tests.rs"]
mod tests;

impl<'ctx, 'src> CssComputeSession<'ctx, 'src> {
    pub(crate) fn new(
        sheet: &'ctx mut CssSheet<'src>,
        element: usize,
        parent: Option<CssPaint<'src>>,
    ) -> Self {
        Self {
            sheet,
            element,
            parent,
            paint: parent.unwrap_or_else(CssPaint::initial),
            winners: [None; PROPERTY_COUNT],
            terminal: None,
            phase: Phase::Initialize,
            property: 0,
            rule: 0,
            declaration: 0,
            matcher: None,
            attribute: None,
            inline: None,
        }
    }

    fn kind(&self) -> WorkKind {
        match self.phase {
            Phase::Match => self.matcher.as_ref().expect("selector matching").kind(),
            Phase::Presentation | Phase::InlineAttribute => WorkKind::TokenVisit,
            Phase::InlineParse => WorkKind::SourceRead,
            _ => WorkKind::PaintVisit,
        }
    }

    pub fn step(
        &mut self,
        quantum: u64,
        control: &mut dyn WorkControl,
    ) -> ControlledStep<(), CssError> {
        if let Some(result) = self.terminal {
            return match result {
                Ok(()) => ControlledStep::Complete(()),
                Err(e) => ControlledStep::Failed(e),
            };
        }
        if let Err(stop) = control.checkpoint() {
            return self.fail(stop.into());
        }
        let mut charged = 0;
        while charged < quantum {
            if let Err(stop) = control.charge(self.kind(), 1) {
                return self.fail(stop.into());
            }
            charged += 1;
            match self.tick() {
                Ok(true) => {
                    self.terminal = Some(Ok(()));
                    return ControlledStep::Complete(());
                }
                Ok(false) => {}
                Err(e) => return self.fail(control::original(e)),
            }
        }
        ControlledStep::Pending {
            charged_units: charged,
        }
    }

    fn fail(&mut self, error: ControlledError<CssError>) -> ControlledStep<(), CssError> {
        self.terminal = Some(Err(error));
        ControlledStep::Failed(error)
    }

    pub fn finish(self) -> Result<CssPaint<'src>, ControlledError<CssError>> {
        self.terminal
            .unwrap_or(Err(ControlledError::Original(CssError::Limit)))?;
        Ok(self.paint)
    }

    fn presentation(&mut self) {
        self.property = 0;
        self.attribute = Some(Attribute::new(self.element, Property::ALL[0].name()));
        self.phase = Phase::Presentation;
    }

    fn tick(&mut self) -> Result<bool, CssError> {
        let source = self.sheet.source;
        let tokens = self.sheet.tokens;
        match self.phase {
            Phase::Initialize => {
                if self
                    .parent
                    .and_then(|paint| paint.source)
                    .is_some_and(|p| !std::ptr::eq(p, source))
                {
                    return Err(CssError::Limit);
                }
                if !tokens.get(self.element).is_some_and(is_element) {
                    return Err(CssError::Limit);
                }
                self.paint.source = Some(source);
                self.property = 0;
                self.phase = Phase::Reset;
            }
            Phase::Reset => {
                let property = Property::ALL[self.property];
                if !inherited(property) {
                    self.paint.values[self.property] = None;
                }
                self.property += 1;
                if self.property == PROPERTY_COUNT {
                    self.phase = Phase::Rule;
                }
            }
            Phase::Rule => {
                if self.rule == self.sheet.rules.len() {
                    self.presentation();
                } else {
                    if self.sheet.match_tests >= MAX_RULE_MATCHES {
                        self.sheet.hit_limit = true;
                        return Err(CssError::Limit);
                    }
                    self.sheet.match_tests += 1;
                    self.matcher = Some(SelectorMatcher::new(
                        self.sheet.rules[self.rule].selector,
                        self.element,
                    ));
                    self.phase = Phase::Match;
                }
            }
            Phase::Match => {
                let result = self.matcher.as_mut().expect("selector matching").tick(
                    source,
                    tokens,
                    &mut self.sheet.selector_visits,
                    &mut self.sheet.hit_limit,
                )?;
                if let Some(matches) = result {
                    self.matcher = None;
                    if matches {
                        let token = &tokens[self.element];
                        if self.sheet.rules[self.rule].unsupported
                            && token.prefix.length == 0
                            && span_eq(source, token.local_name, b"stop")
                        {
                            return Err(CssError::Unsupported);
                        }
                        self.declaration = 0;
                        self.phase = Phase::Offer;
                    } else {
                        self.rule += 1;
                        self.phase = Phase::Rule;
                    }
                }
            }
            Phase::Offer => {
                let rule = &self.sheet.rules[self.rule];
                if self.declaration == rule.declarations.len() {
                    self.rule += 1;
                    self.phase = Phase::Rule;
                } else {
                    offer(
                        &mut self.winners,
                        rule.declarations[self.declaration],
                        rule.selector.specificity,
                        rule.order
                            .saturating_mul(MAX_DECLARATIONS)
                            .saturating_add(self.declaration),
                    );
                    self.declaration += 1;
                }
            }
            Phase::Presentation => {
                let attr = self.attribute.as_mut().expect("presentation attribute");
                if attr.tick(source, tokens) {
                    if let Some(value) = attr.result {
                        offer(
                            &mut self.winners,
                            Declaration {
                                property: Property::ALL[self.property],
                                value,
                                important: false,
                            },
                            0,
                            0,
                        );
                    }
                    self.property += 1;
                    if self.property == PROPERTY_COUNT {
                        self.attribute = Some(Attribute::new(self.element, b"style"));
                        self.phase = Phase::InlineAttribute;
                    } else {
                        self.attribute = Some(Attribute::new(
                            self.element,
                            Property::ALL[self.property].name(),
                        ));
                    }
                }
            }
            Phase::InlineAttribute => {
                let attr = self.attribute.as_mut().expect("inline attribute");
                if attr.tick(source, tokens) {
                    if let Some(style) = attr.result {
                        if style.length > MAX_BYTES {
                            return Err(CssError::Limit);
                        }
                        self.inline = Some(Declarations::new(source, style)?);
                        self.phase = Phase::InlineParse;
                    } else {
                        self.property = 0;
                        self.phase = Phase::Winner;
                    }
                }
            }
            Phase::InlineParse => {
                let parser = self.inline.as_mut().expect("inline parser");
                let result = parser.tick(source);
                self.sheet.hit_limit |= parser.hit_limit;
                if result? {
                    self.declaration = 0;
                    self.phase = Phase::InlineOffer;
                }
            }
            Phase::InlineOffer => {
                let output = &self.inline.as_ref().expect("inline parser").output;
                if self.declaration == output.len() {
                    self.inline = None;
                    self.property = 0;
                    self.phase = Phase::Winner;
                } else {
                    offer(
                        &mut self.winners,
                        output[self.declaration],
                        1_000_000,
                        self.declaration,
                    );
                    self.declaration += 1;
                }
            }
            Phase::Winner => {
                let property = Property::ALL[self.property];
                if let Some(winner) = self.winners[self.property] {
                    let value = checked_slice(source, winner.value)?;
                    // These three fixed keyword comparisons inspect at most 19 bytes in total.
                    // All long value scanning is retained in the declaration parser above.
                    if value.eq_ignore_ascii_case(b"inherit")
                        || (value.eq_ignore_ascii_case(b"unset") && inherited(property))
                    {
                        self.paint.values[self.property] =
                            self.parent.and_then(|p| p.value(property));
                    } else if value.eq_ignore_ascii_case(b"initial")
                        || value.eq_ignore_ascii_case(b"unset")
                    {
                        self.paint.values[self.property] = None;
                    } else {
                        self.paint.values[self.property] = Some(CssValue {
                            span: winner.value,
                            bytes: value,
                        });
                    }
                }
                self.property += 1;
                if self.property == PROPERTY_COUNT {
                    self.phase = Phase::Done;
                }
            }
            Phase::Done => return Ok(true),
        }
        Ok(matches!(self.phase, Phase::Done))
    }
}

use crate::{MAX_CLASSES, MAX_SELECTOR_TERMS, Selector, Term, XmlSpan, ident, is_space};

#[derive(Clone, Copy)]
enum Phase {
    Right,
    Left,
    Begin,
    Identifier,
    Compound,
    FinishTerm,
    Space,
    Done,
}

pub(crate) struct SelectorParser {
    phase: Phase,
    start: usize,
    end: usize,
    cursor: usize,
    begin: usize,
    marker: u8,
    spaced: bool,
    term: Term,
    selector: Selector,
    valid: bool,
}
impl SelectorParser {
    pub fn new(start: usize, end: usize) -> Self {
        Self {
            phase: Phase::Right,
            start,
            end,
            cursor: start,
            begin: start,
            marker: 0,
            spaced: false,
            term: Term::EMPTY,
            selector: Selector::EMPTY,
            valid: true,
        }
    }
    fn reject(&mut self) {
        self.valid = false;
        self.phase = Phase::Done;
    }
    pub fn result(&self) -> Option<Selector> {
        (self.valid && self.selector.count > 0).then_some(self.selector)
    }
    pub fn tick(&mut self, source: &[u8]) -> bool {
        match self.phase {
            Phase::Right => {
                if self.end > self.start && is_space(source[self.end - 1]) {
                    self.end -= 1;
                } else {
                    self.phase = Phase::Left;
                }
            }
            Phase::Left => {
                if self.start < self.end && is_space(source[self.start]) {
                    self.start += 1;
                } else {
                    self.cursor = self.start;
                    self.phase = Phase::Begin;
                }
            }
            Phase::Begin => {
                if self.cursor >= self.end {
                    self.phase = Phase::Done;
                } else if self.selector.count == MAX_SELECTOR_TERMS {
                    self.reject();
                } else {
                    self.term = Term::EMPTY;
                    if matches!(source[self.cursor], b'#' | b'.') {
                        self.phase = Phase::Compound;
                    } else {
                        self.marker = 0;
                        self.begin = self.cursor;
                        self.phase = Phase::Identifier;
                    }
                }
            }
            Phase::Identifier => {
                if self.cursor < self.end && ident(source[self.cursor]) {
                    self.cursor += 1;
                } else if self.begin == self.cursor {
                    self.reject();
                } else {
                    let span = XmlSpan {
                        offset: self.begin,
                        length: self.cursor - self.begin,
                    };
                    match self.marker {
                        0 => {
                            self.term.element = Some(span);
                            self.term.specificity += 1;
                        }
                        b'#' if self.term.id.is_none() => {
                            self.term.id = Some(span);
                            self.term.specificity += 10_000;
                        }
                        b'.' if self.term.class_count < MAX_CLASSES => {
                            self.term.classes[self.term.class_count] = span;
                            self.term.class_count += 1;
                            self.term.specificity += 100;
                        }
                        _ => {
                            self.reject();
                            return true;
                        }
                    }
                    self.phase = Phase::Compound;
                }
            }
            Phase::Compound => {
                if self.cursor < self.end && matches!(source[self.cursor], b'#' | b'.') {
                    self.marker = source[self.cursor];
                    self.cursor += 1;
                    self.begin = self.cursor;
                    self.phase = Phase::Identifier;
                } else {
                    self.phase = Phase::FinishTerm;
                }
            }
            Phase::FinishTerm => {
                if self.term.element.is_none()
                    && self.term.id.is_none()
                    && self.term.class_count == 0
                {
                    self.reject();
                } else if let Some(specificity) =
                    self.selector.specificity.checked_add(self.term.specificity)
                {
                    self.selector.specificity = specificity;
                    self.selector.terms[self.selector.count] = self.term;
                    self.selector.count += 1;
                    self.spaced = false;
                    self.phase = Phase::Space;
                } else {
                    self.reject();
                }
            }
            Phase::Space => {
                if self.cursor < self.end && is_space(source[self.cursor]) {
                    self.cursor += 1;
                    self.spaced = true;
                } else if self.cursor < self.end
                    && (!self.spaced || matches!(source[self.cursor], b'>' | b'+' | b'~'))
                {
                    self.reject();
                } else {
                    self.phase = Phase::Begin;
                }
            }
            Phase::Done => return true,
        }
        matches!(self.phase, Phase::Done)
    }
}
use crate::{
    CssError, MAX_RULE_MATCHES, Selector, Term, TokenKind, XmlSpan, XmlToken, checked_slice,
    is_element, is_space, span_eq,
};
use vexel_base::WorkKind;

/// Attribute names are compared only to fixed literals (max 26 bytes). One tick visits one token.
pub(crate) struct Attribute {
    cursor: Option<usize>,
    name: &'static [u8],
    pub result: Option<XmlSpan>,
}
impl Attribute {
    pub fn new(element: usize, name: &'static [u8]) -> Self {
        Self {
            cursor: element.checked_add(1),
            name,
            result: None,
        }
    }
    pub fn tick(&mut self, source: &[u8], tokens: &[XmlToken]) -> bool {
        let Some(i) = self.cursor else { return true };
        let Some(token) = tokens.get(i).filter(|t| t.kind == TokenKind::Attribute) else {
            self.cursor = None;
            return true;
        };
        if token.prefix.length == 0 && span_eq(source, token.local_name, self.name) {
            self.result = Some(token.value);
            self.cursor = None;
            return true;
        }
        self.cursor = i.checked_add(1);
        false
    }
}

/// Each tick compares one byte. Invalid ID spans preserve the baseline Option equality.
struct Compare<'src> {
    a: Option<&'src [u8]>,
    b: Option<&'src [u8]>,
    cursor: usize,
    invalid_equal: bool,
}
impl<'src> Compare<'src> {
    fn new(a: Option<&'src [u8]>, b: Option<&'src [u8]>, invalid_equal: bool) -> Self {
        Self {
            a,
            b,
            cursor: 0,
            invalid_equal,
        }
    }
    fn tick(&mut self) -> Option<bool> {
        match (self.a, self.b) {
            (Some(a), Some(b)) if a.len() == b.len() => {
                if self.cursor == a.len() {
                    return Some(true);
                }
                if a[self.cursor] != b[self.cursor] {
                    return Some(false);
                }
                self.cursor += 1;
                (self.cursor == a.len()).then_some(true)
            }
            (None, None) => Some(self.invalid_equal),
            _ => Some(false),
        }
    }
}

#[derive(Clone, Copy)]
enum ClassPhase {
    Skip,
    Start,
    Word,
    Compare,
}
struct Class<'src> {
    value: Option<&'src [u8]>,
    wanted: Option<&'src [u8]>,
    cursor: usize,
    start: usize,
    count: usize,
    phase: ClassPhase,
    compare: Option<Compare<'src>>,
}
impl<'src> Class<'src> {
    fn new(source: &'src [u8], value: XmlSpan, wanted: XmlSpan) -> Self {
        Self {
            value: checked_slice(source, value).ok(),
            wanted: checked_slice(source, wanted).ok(),
            cursor: 0,
            start: 0,
            count: 0,
            phase: ClassPhase::Skip,
            compare: None,
        }
    }
    fn tick(&mut self) -> Option<bool> {
        let (Some(value), Some(wanted)) = (self.value, self.wanted) else {
            return Some(false);
        };
        match self.phase {
            ClassPhase::Skip => {
                if self.cursor == value.len() {
                    return Some(false);
                }
                if is_space(value[self.cursor]) {
                    self.cursor += 1;
                } else {
                    self.phase = ClassPhase::Start;
                }
            }
            ClassPhase::Start => {
                self.count += 1;
                if self.count > 256 {
                    return Some(false);
                }
                self.start = self.cursor;
                self.phase = ClassPhase::Word;
            }
            ClassPhase::Word => {
                if self.cursor < value.len() && !is_space(value[self.cursor]) {
                    self.cursor += 1;
                } else {
                    self.compare = Some(Compare::new(
                        Some(&value[self.start..self.cursor]),
                        Some(wanted),
                        false,
                    ));
                    self.phase = ClassPhase::Compare;
                }
            }
            ClassPhase::Compare => {
                if let Some(matches) = self.compare.as_mut().expect("class comparison").tick() {
                    if matches {
                        return Some(true);
                    }
                    self.compare = None;
                    self.phase = ClassPhase::Skip;
                }
            }
        }
        None
    }
}

#[derive(Clone, Copy)]
enum TermPhase {
    Begin,
    Element,
    FindId,
    Id,
    FindClass,
    Class,
    Done,
}
struct TermMatcher<'src> {
    term: Term,
    element: usize,
    phase: TermPhase,
    attribute: Option<Attribute>,
    compare: Option<Compare<'src>>,
    class: Option<Class<'src>>,
    class_index: usize,
    class_value: XmlSpan,
    result: bool,
}
impl<'src> TermMatcher<'src> {
    fn new(term: Term, element: usize) -> Self {
        Self {
            term,
            element,
            phase: TermPhase::Begin,
            attribute: None,
            compare: None,
            class: None,
            class_index: 0,
            class_value: XmlSpan {
                offset: 0,
                length: 0,
            },
            result: false,
        }
    }
    fn kind(&self) -> WorkKind {
        match self.phase {
            TermPhase::FindId | TermPhase::FindClass => WorkKind::TokenVisit,
            _ => WorkKind::SourceRead,
        }
    }
    fn finish(&mut self, result: bool) {
        self.result = result;
        self.phase = TermPhase::Done;
    }
    fn id(&mut self) {
        if self.term.id.is_some() {
            self.attribute = Some(Attribute::new(self.element, b"id"));
            self.phase = TermPhase::FindId;
        } else {
            self.classes();
        }
    }
    fn classes(&mut self) {
        if self.term.class_count > 0 {
            self.attribute = Some(Attribute::new(self.element, b"class"));
            self.phase = TermPhase::FindClass;
        } else {
            self.finish(true);
        }
    }
    fn tick(&mut self, source: &'src [u8], tokens: &[XmlToken]) -> Option<bool> {
        match self.phase {
            TermPhase::Begin => {
                if let Some(name) = self.term.element {
                    let local =
                        checked_slice(source, tokens[self.element].local_name).unwrap_or_default();
                    self.compare = Some(Compare::new(
                        checked_slice(source, name).ok(),
                        Some(local),
                        false,
                    ));
                    self.phase = TermPhase::Element;
                } else {
                    self.id();
                }
            }
            TermPhase::Element => {
                if let Some(matches) = self.compare.as_mut().expect("element comparison").tick() {
                    if matches {
                        self.id();
                    } else {
                        self.finish(false);
                    }
                }
            }
            TermPhase::FindId => {
                let attr = self.attribute.as_mut().expect("id lookup");
                if attr.tick(source, tokens) {
                    if let Some(value) = attr.result {
                        self.compare = Some(Compare::new(
                            checked_slice(source, value).ok(),
                            checked_slice(source, self.term.id.expect("id span")).ok(),
                            true,
                        ));
                        self.phase = TermPhase::Id;
                    } else {
                        self.finish(false);
                    }
                }
            }
            TermPhase::Id => {
                if let Some(matches) = self.compare.as_mut().expect("id comparison").tick() {
                    if matches {
                        self.classes();
                    } else {
                        self.finish(false);
                    }
                }
            }
            TermPhase::FindClass => {
                let attr = self.attribute.as_mut().expect("class lookup");
                if attr.tick(source, tokens) {
                    if let Some(value) = attr.result {
                        self.class_value = value;
                        self.class_index = 0;
                        self.class = Some(Class::new(source, value, self.term.classes[0]));
                        self.phase = TermPhase::Class;
                    } else {
                        self.finish(false);
                    }
                }
            }
            TermPhase::Class => {
                if let Some(matches) = self.class.as_mut().expect("class scan").tick() {
                    if !matches {
                        self.finish(false);
                    } else {
                        self.class_index += 1;
                        if self.class_index == self.term.class_count {
                            self.finish(true);
                        } else {
                            self.class = Some(Class::new(
                                source,
                                self.class_value,
                                self.term.classes[self.class_index],
                            ));
                        }
                    }
                }
            }
            TermPhase::Done => return Some(self.result),
        }
        matches!(self.phase, TermPhase::Done).then_some(self.result)
    }
}

#[derive(Clone, Copy)]
enum MatchPhase {
    Begin,
    Term,
    Ancestor,
    Done,
}
pub(crate) struct SelectorMatcher<'src> {
    selector: Selector,
    phase: MatchPhase,
    term_index: usize,
    descendant: usize,
    cursor: usize,
    candidate: usize,
    rightmost: bool,
    term: Option<TermMatcher<'src>>,
    result: bool,
}
impl<'src> SelectorMatcher<'src> {
    pub fn new(selector: Selector, element: usize) -> Self {
        Self {
            selector,
            phase: MatchPhase::Begin,
            term_index: 0,
            descendant: element,
            cursor: element,
            candidate: element,
            rightmost: true,
            term: None,
            result: false,
        }
    }
    pub fn kind(&self) -> WorkKind {
        if matches!(self.phase, MatchPhase::Term) {
            self.term.as_ref().expect("term matching").kind()
        } else {
            WorkKind::TokenVisit
        }
    }
    fn finish(&mut self, result: bool) {
        self.result = result;
        self.phase = MatchPhase::Done;
    }
    pub fn tick(
        &mut self,
        source: &'src [u8],
        tokens: &[XmlToken],
        selector_visits: &mut usize,
        hit_limit: &mut bool,
    ) -> Result<Option<bool>, CssError> {
        match self.phase {
            MatchPhase::Begin => {
                if self.selector.count == 0 {
                    self.finish(false);
                } else {
                    self.term_index = self.selector.count - 1;
                    self.term = Some(TermMatcher::new(
                        self.selector.terms[self.term_index],
                        self.descendant,
                    ));
                    self.phase = MatchPhase::Term;
                }
            }
            MatchPhase::Term => {
                if let Some(matches) = self
                    .term
                    .as_mut()
                    .expect("term matching")
                    .tick(source, tokens)
                {
                    if matches {
                        self.descendant = self.candidate;
                        if self.term_index == 0 {
                            self.finish(true);
                        } else {
                            self.term_index -= 1;
                            self.cursor = self.descendant;
                            self.rightmost = false;
                            self.phase = MatchPhase::Ancestor;
                        }
                    } else if self.rightmost {
                        self.finish(false);
                    } else {
                        self.phase = MatchPhase::Ancestor;
                    }
                }
            }
            MatchPhase::Ancestor => {
                if self.cursor == 0 {
                    self.finish(false);
                } else {
                    self.cursor -= 1;
                    let token = &tokens[self.cursor];
                    if is_element(token) && token.depth < tokens[self.descendant].depth {
                        if *selector_visits >= MAX_RULE_MATCHES {
                            *hit_limit = true;
                            return Err(CssError::Limit);
                        }
                        *selector_visits += 1;
                        self.candidate = self.cursor;
                        self.term = Some(TermMatcher::new(
                            self.selector.terms[self.term_index],
                            self.candidate,
                        ));
                        self.phase = MatchPhase::Term;
                    }
                }
            }
            MatchPhase::Done => return Ok(Some(self.result)),
        }
        Ok(matches!(self.phase, MatchPhase::Done).then_some(self.result))
    }
}

